function origin(){return(process.env.ALPHALAB_API_ORIGIN||'http://127.0.0.1:8000').replace(/\/+$/,'')}
async function get(path){const response=await fetch(origin()+path,{headers:{Accept:'application/json'}});if(!response.ok)throw new Error('AlphaLab API '+response.status+': '+await response.text());return response.json()}
async function run(input){const id=String(input.project_id||'').trim();if(!id)throw new Error('project_id is required');const value=await get('/api/strategy/projects/'+encodeURIComponent(id));const available=typeof value.strategy_source==='string';let entrypoint_source=null;if(input.entrypoint_id)entrypoint_source=await get('/api/strategy/projects/'+encodeURIComponent(id)+'/entrypoints/'+encodeURIComponent(String(input.entrypoint_id))+'/source');if(input.include_source!==true){delete value.draft_source;delete value.strategy_source}return{...value,entrypoint_source,source_available:available,source_included:available&&input.include_source===true}}
